import pytest

def normalize_status(value: str) -> str:
    """
    Normalize a status string by stripping whitespace and converting to lowercase.

    Args:
        value: The input status string to normalize.

    Returns:
        The normalized status string.
    """
    return value.strip().lower()

@pytest.mark.unit
def test_normalize_status_normal():
    """Test with a normal input string."""
    assert normalize_status("Ready") == "ready"

@pytest.mark.unit
def test_normalize_status_blank():
    """Test with a blank input string."""
    assert normalize_status("") == ""

@pytest.mark.unit
def test_normalize_status_whitespace():
    """Test with a whitespace-only input string."""
    assert normalize_status("   ") == ""

@pytest.mark.unit
def test_normalize_status_mixed_case():
    """Test with a mixed case input string."""
    assert normalize_status("HeAdEr") == "header"

@pytest.mark.unit
def test_normalize_status_space_padded():
    """Test with space padded input as per fact table."""
    assert normalize_status("  READY  ") == "ready"
